<?php
require_once 'includes/config.php'; require_once 'includes/phase3.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['mark_all'])){notification_mark_all_read($dbh,'admin',(int)$_SESSION['admin_id']);audit_log($dbh,'NOTIFICATIONS_READ','Marked all admin notifications as read');header('Location: notifications.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['mark_id'])){$id=(int)$_POST['mark_id'];$q=$dbh->prepare('UPDATE notifications SET is_read=1,read_at=NOW() WHERE id=:id AND recipient_type=\'admin\' AND recipient_id=:r');$q->execute([':id'=>$id,':r'=>$_SESSION['admin_id']]);header('Location: notifications.php');exit;}
$q=$dbh->prepare('SELECT * FROM notifications WHERE recipient_type=\'admin\' AND recipient_id=:r ORDER BY is_read ASC,created_at DESC LIMIT 100');$q->execute([':r'=>$_SESSION['admin_id']]);$rows=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><div class="main-page"><div class="container-fluid"><div class="row page-title-div"><div class="col-sm-8"><h2 class="title">Notifications</h2></div><div class="col-sm-4 text-right"><form method="post"><?php echo csrf_field();?><button class="btn btn-default" name="mark_all" value="1">Mark all as read</button></form></div></div><div class="panel"><div class="panel-body"><?php foreach($rows as $r):?><div class="media" style="padding:12px;border-bottom:1px solid #eee;background:<?php echo $r['is_read']?'#fff':'#f5f9ff';?>"><div class="media-left"><i class="fa fa-<?php echo $r['type']==='success'?'check-circle':($r['type']==='danger'?'warning':'bell');?> fa-2x"></i></div><div class="media-body"><strong><?php echo e($r['title']);?></strong><br><?php echo e($r['message']);?><br><small class="text-muted"><?php echo e($r['created_at']);?></small><?php if(!$r['is_read']):?><form method="post" class="pull-right"><?php echo csrf_field();?><input type="hidden" name="mark_id" value="<?php echo $r['id'];?>"><button class="btn btn-xs btn-link">Mark read</button></form><?php endif;?><?php if($r['link']):?><a class="btn btn-xs btn-primary pull-right" href="<?php echo e($r['link']);?>">Open</a><?php endif;?></div></div><?php endforeach;?><?php if(!$rows):?><p class="text-center text-muted">No notifications.</p><?php endif;?></div></div></div></div></div></div></div><script src="js/jquery/jquery-2.2.4.min.js"></script><script src="js/bootstrap/bootstrap.min.js"></script></body></html>
